from taf.ul.ettf.typed.custom_types import Margin, ThroughputValue, List
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.utils.exception import LibraryError
from abc import ABCMeta, abstractmethod
from six import with_metaclass


class InvalidThroughputError(LibraryError):
    pass


class AssertionCondition(with_metaclass(ABCMeta, object)):
    @typed(expected_throughput=ThroughputValue())
    def __init__(self, expected_throughput):
        self._expected_throughput = expected_throughput

    @abstractmethod
    def __call__(self, *args, **kwargs):
        pass


class EqualsTo(AssertionCondition):
    @typed(margin=Margin(), extracted_value=ThroughputValue())
    def __call__(self, extracted_value, margin=.0):
        relative_value = extracted_value / self._expected_throughput
        if relative_value < 1 - margin:
            raise InvalidThroughputError("Throughput lower bound not reached",
                                         'Expected: {}. Got: {}'.format(self._expected_throughput, extracted_value))
        if relative_value > 1 + margin:
            raise InvalidThroughputError("Throughput upper bound exceeded",
                                         'Expected: {}. Got: {}'.format(self._expected_throughput, extracted_value))


class Reaches(AssertionCondition):
    @typed(margin=Margin(), extracted_value=ThroughputValue())
    def __call__(self, extracted_value, margin=.0):
        relative_value = extracted_value / self._expected_throughput
        if relative_value < 1 - margin:
            raise InvalidThroughputError("Throughput lower bound not reached",
                                         'Expected: {}. Got: {}'.format(self._expected_throughput, extracted_value))


class EvenDistribution(object):
    @typed(margin=Margin(), extracted_values=List(ThroughputValue()))
    def __call__(self, extracted_values, margin=.0):
        average = self._get_average(extracted_values)
        for value in extracted_values:
            if not 1 - margin < value / average < 1 + margin:
                raise InvalidThroughputError("Throughput outside of accepted margin: {}".format(margin),
                                             'Average: {}. Got: {}'.format(average, value))

    def _get_average(self, extracted_values):
        return sum(extracted_values) / len(extracted_values)
